(2896000, 404372, 33672, '<td valign="top">Great, great idea and comp. (Besides I really like this beer) Nice condensation makes attractive presentation.  Foam,bubbles and pouring beer  need to be a bit sharper. Comp lends itself well to text placement.</td>', 'Great, great idea and comp. (Besides I really like this beer) Nice condensation makes attractive presentation.  Foam,bubbles and pouring beer  need to be a bit sharper. Comp lends itself well to text placement.', '2006-10-04 14:14:19.000000', NULL, 1),
(2896005, 405953, 33672, '<td valign="top">Attractive macro with a lot of potential for advertising. Lots of great places for text. lighting is just a bit harsh as it reflect in the bubbles. Pouring soda should be a bit sharper for the full effect.</td>', 'Attractive macro with a lot of potential for advertising. Lots of great places for text. lighting is just a bit harsh as it reflect in the bubbles. Pouring soda should be a bit sharper for the full effect.', '2006-10-04 14:16:11.000000', NULL, 1),
