(2902498, 405786, 16477, '<td valign="top">Love the lighting, love the whole setup i.e.  white BG, White sheet etc, 10</td>', 'Love the lighting, love the whole setup i.e.  white BG, White sheet etc, 10', '2006-10-06 10:34:12.000000', NULL, 1),
(2902505, 405635, 16477, '<td valign="top">I feel it has been shot in natural lighting, nice, could have been better, 7</td>', 'I feel it has been shot in natural lighting, nice, could have been better, 7', '2006-10-06 10:35:48.000000', NULL, 1),
