(2912230, 404699, 47020, '<td valign="top">I can''t imagine this ever being an actual ad, but I do find it amusing.  :-)</td>', 'I can''t imagine this ever being an actual ad, but I do find it amusing.  :-)', '2006-10-09 18:19:47.000000', NULL, 1),
(2912237, 405867, 48588, '<td valign="top">Wow, this image makes me WANT to buy a Corona.  Well done!</td>', 'Wow, this image makes me WANT to buy a Corona.  Well done!', '2006-10-09 18:21:45.000000', NULL, 1),
