(2912244, 405725, 48588, '<td valign="top">I can see this with text in the empty space, neat idea.  Less glare on the can would be nice though.</td>', 'I can see this with text in the empty space, neat idea.  Less glare on the can would be nice though.', '2006-10-09 18:23:13.000000', NULL, 1),
(2912247, 405281, 48588, '<td valign="top">The low battery icon makes me think Coke saps your energy.  This would not make me want to buy a Coke.</td>', 'The low battery icon makes me think Coke saps your energy.  This would not make me want to buy a Coke.', '2006-10-09 18:24:18.000000', NULL, 1),
(2912249, 405003, 48588, '<td valign="top">Very nice!  This looks like it could''ve been taken at my house, and I love that.  Great work!</td>', 'Very nice!  This looks like it could''ve been taken at my house, and I love that.  Great work!', '2006-10-09 18:25:16.000000', NULL, 1),
(2912253, 405595, 48588, '<td valign="top">I like it ...</td>', 'I like it ...', '2006-10-09 18:26:35.000000', NULL, 1),
(2912254, 405000, 48588, '<td valign="top">I find her shirt distracting ...</td>', 'I find her shirt distracting ...', '2006-10-09 18:26:59.000000', NULL, 1),
