(2912276, 405959, 48588, '<td valign="top">Too funny!</td>', 'Too funny!', '2006-10-09 18:33:25.000000', NULL, 1),
(2912559, 405096, 35602, '<td valign="top">Very cool.  Not sure how you did it, but I will check when challenge is over.  The only thing I wonder about is why there is no product name on the label.  Since it is an ad, I think that might have been an important point.</td>', 'Very cool.  Not sure how you did it, but I will check when challenge is over.  The only thing I wonder about is why there is no product name on the label.  Since it is an ad, I think that might have been an important point.', '2006-10-09 20:49:53.000000', NULL, 1),
(2912568, 405867, 35602, '<td valign="top">I love the concept of this one.  A bit more crop to focus more on the product would have really brought it out better.  It is the product you are selling, not the background.  8</td>', 'I love the concept of this one.  A bit more crop to focus more on the product would have really brought it out better.  It is the product you are selling, not the background.  8', '2006-10-09 20:54:57.000000', NULL, 1),
(2912577, 402429, 35602, '<td valign="top">Very good concept.  Saw one like this on a billboard, so you did a fine job of depicting it in a way the advertising market would jump on.  I know it is basic editing, so spot editing is not allowed, but the overexposed line at the bottom is distracting.  Still, overall, you used dramatic lighting to highlight the product.  8</td>', 'Very good concept.  Saw one like this on a billboard, so you did a fine job of depicting it in a way the advertising market would jump on.  I know it is basic editing, so spot editing is not allowed, but the overexposed line at the bottom is distracting.  Still, overall, you used dramatic lighting to highlight the product.  8', '2006-10-09 20:58:34.000000', NULL, 1),
(2912582, 402740, 35602, '<td valign="top">Except for the title, this shows no product.  Number one rule in advertising, you need to show the product somewhere.  As a black and white, your contrast is very good with plenty of lights and darks.</td>', 'Except for the title, this shows no product.  Number one rule in advertising, you need to show the product somewhere.  As a black and white, your contrast is very good with plenty of lights and darks.', '2006-10-09 21:00:47.000000', NULL, 1),
(2912584, 403113, 35602, '<td valign="top">I think the post processing made the image too painted looking.</td>', 'I think the post processing made the image too painted looking.', '2006-10-09 21:01:49.000000', NULL, 1),
(2912589, 405328, 35602, '<td valign="top">Yep, sex sells.  Great image.  Definitely one for Sports Illustrated, or one of those other sports mags.</td>', 'Yep, sex sells.  Great image.  Definitely one for Sports Illustrated, or one of those other sports mags.', '2006-10-09 21:04:06.000000', NULL, 1),
(2912618, 404976, 35602, '<td valign="top">Really nice photo.  Lighting is great, and you really made the foreground bottle stand out with that wonderful yellow light behind it.  Great job.</td>', 'Really nice photo.  Lighting is great, and you really made the foreground bottle stand out with that wonderful yellow light behind it.  Great job.', '2006-10-09 21:20:25.000000', NULL, 1),
(2912622, 406032, 35602, '<td valign="top">I cracked up on this one.  Oh my God, what a great job you did.  Don''t know how great an ad it makes, but it is definitely very politically charged, and I love it.</td>', 'I cracked up on this one.  Oh my God, what a great job you did.  Don''t know how great an ad it makes, but it is definitely very politically charged, and I love it.', '2006-10-09 21:22:06.000000', NULL, 1),
(2912646, 402728, 52500, '<td valign="top">Fabulous idea, perfectly executed.</td>', 'Fabulous idea, perfectly executed.', '2006-10-09 21:38:33.000000', NULL, 1),
(2912652, 402728, 35567, '<td valign="top">I really like this picture. The stop motion of the liquid is great, but for me the background is what really makes this one pop. 9</td>', 'I really like this picture. The stop motion of the liquid is great, but for me the background is what really makes this one pop. 9', '2006-10-09 21:42:02.000000', NULL, 1),
(2912655, 405781, 35567, '<td valign="top">The lighting and the motion are great, 8</td>', 'The lighting and the motion are great, 8', '2006-10-09 21:43:24.000000', NULL, 1),
