(2912686, 405976, 20568, '<td valign="top">Great clarity...great beer!  I''m giving it a 9!</td>', 'Great clarity...great beer!  I''m giving it a 9!', '2006-10-09 21:54:08.000000', NULL, 1),
(2912688, 405783, 20568, '<td valign="top">I like it...very real.</td>', 'I like it...very real.', '2006-10-09 21:54:35.000000', NULL, 1),
