(2917143, 405921, 61191, '<td valign="top">Congrats on the 15th Crystal!<br/>Cool "oldskool" shot, I like it.</td>', 'Congrats on the 15th Crystal!Cool "oldskool" shot, I like it.', '2006-10-11 07:59:20.000000', NULL, 0),
(2917146, 405867, 37719, '<td valign="top">Congratulations Jimmy! Excellent shot!  Very well done!  It is about time the others started recognizing your talent.  Very well deserved in my opinion.  I didn''t vote this challenge, but after perusing the entries I think the right image landed the blue.  Excellent exposure, perfect composition, perfect combination of title, concept, photograph.  Extremely well executed!  Would have been a solid 10 from me.  Again, congrats, you deserve it!<br/><br/><i>Message edited by author 2006-10-11 16:55:36.</i></td>', 'Congratulations Jimmy! Excellent shot!  Very well done!  It is about time the others started recognizing your talent.  Very well deserved in my opinion.  I didn''t vote this challenge, but after perusing the entries I think the right image landed the blue.  Excellent exposure, perfect composition, perfect combination of title, concept, photograph.  Extremely well executed!  Would have been a solid 10 from me.  Again, congrats, you deserve it!', '2006-10-11 08:01:12.000000', '2006-10-11 17:55:36.000000', 0),
(2917147, 405755, 56797, '<td valign="top">awwwwww. 5.39?!  I gave you an 8. this is a really great shot! VERY funny but technically great too.</td>', 'awwwwww. 5.39?!  I gave you an 8. this is a really great shot! VERY funny but technically great too.', '2006-10-11 08:01:45.000000', NULL, 0),
(2917168, 405867, 40386, '<td valign="top">Way to go Jimmy!  I knew this would ribbon, my favorite of the challenge.  There is just no stopping you with that new Canon LOL.<br/>Cant wait to see your future entries.</td>', 'Way to go Jimmy!  I knew this would ribbon, my favorite of the challenge.  There is just no stopping you with that new Canon LOL.Cant wait to see your future entries.', '2006-10-11 08:07:33.000000', NULL, 0),
(2917176, 405755, 29490, '<td valign="top">''Flavored with Tears''!!  LOL That''s hilarious! :)<br/> <br/>Too bad voters suck, should have scored higher :(</td>', '''Flavored with Tears''!!  LOL That''s hilarious! :) Too bad voters suck, should have scored higher :(', '2006-10-11 08:13:29.000000', NULL, 0),
